#!/usr/bin/env bash
# Run one stack-detector scan as a Job inside the selected cluster and print its
# JSON report. The script deletes nothing: the first run creates the scan's
# ServiceAccount, ClusterRole and ClusterRoleBinding, later runs reuse them, and
# Kubernetes removes each finished Job after JOB_TTL_SECONDS.
# Published at:
#   https://raw.githubusercontent.com/cipherops-io/rtifact-alert-rules/main/setup/kubernetes/stack-detector.sh
# That copy is generated by CI from cipherops-io/rt-stack-detector
# scripts/stack-detector on each rtifact/live release. Edit the source, not the copy.
set -euo pipefail
umask 077

# CI replaces this placeholder with the published, digest-pinned image.
STACK_DETECTOR_IMAGE="${STACK_DETECTOR_IMAGE:-ghcr.io/cipherops-io/stack-detector@sha256:f48dc73e1f2ed5f4f33b236563681e19ba42d59610a08fbda6212a0eb072dcaa}"
# Must match ReportBegin and ReportEnd in internal/cli/scan.go.
REPORT_BEGIN='----- BEGIN RT-STACK-DETECTOR REPORT -----'
REPORT_END='----- END RT-STACK-DETECTOR REPORT -----'
# Time allowed for scheduling and image pull, on top of the scan timeout.
START_ALLOWANCE_SECONDS=300
# The ServiceAccount, ClusterRole and ClusterRoleBinding that every run shares.
ACCESS_NAME="rt-stack-detector-scan"
# Holds --detection-catalog; each run that passes one replaces its contents.
CATALOG_NAME="rt-stack-detector-scan-catalog"
# Kubernetes deletes a finished scan Job and its pod after this long.
JOB_TTL_SECONDS=900

context=""
kubeconfig=""
namespace="rtifact-system"
output_file=""
timeout="5m"
include=""
exclude=""
probe_metrics=true
catalog=""
image="$STACK_DETECTOR_IMAGE"
pull_secret=""

name=""
run_id=""
tmp=""
has_namespace=false
has_account=false
has_role=false
has_binding=false
missing_permissions=""
kube_args=()

info() { printf '[stack-detector] %s\n' "$*" >&2; }
fail() { info "ERROR: $*"; exit 1; }

usage() {
    cat <<'HELP'
Usage: stack-detector [options] > report.json

Runs one scan as a Job inside the cluster, so metrics endpoints are checked
from the cluster network. Prints the JSON report on stdout and progress on
stderr. Nothing is deleted: the first run creates a ServiceAccount, ClusterRole
and ClusterRoleBinding named rt-stack-detector-scan that later runs reuse, and
Kubernetes removes each finished Job after 15 minutes.

  --context NAME              kubeconfig context (default: current context)
  --kubeconfig PATH           kubeconfig file (default: KUBECONFIG or ~/.kube/config)
  --namespace NAME            namespace for the Job (default: rtifact-system;
                              created if it does not exist)
  --output-file PATH          also save the JSON report to this file
  --timeout DURATION          scan timeout, e.g. 300s or 10m (default: 5m)
  --include-namespaces LIST   comma-separated namespaces to scan
  --exclude-namespaces LIST   comma-separated namespaces to skip
                              (exclude wins; '*' matches any characters,
                              e.g. 'rtifact-*'; quote it so the shell keeps it)
  --probe-metrics BOOL        verify metrics endpoints (default: true)
  --detection-catalog PATH    YAML catalog overlay, mounted into the Job
  --image IMAGE               scanner image (default: the published release)
  --image-pull-secret NAME    existing registry Secret in --namespace
  --help                      show this help

Requires kubectl and permission to create Jobs and read pod logs in the
namespace. Until the ServiceAccount, ClusterRole and ClusterRoleBinding exist,
it also needs permission to create them (cluster-admin works).
HELP
}

parse_args() {
    local arg value has_value
    while [ "$#" -gt 0 ]; do
        arg="$1"
        shift
        has_value=false
        value=""
        case "$arg" in
            --*=*) value="${arg#*=}"; arg="${arg%%=*}"; has_value=true ;;
        esac
        case "$arg" in
            -h|--help) usage; exit 0 ;;
            --context|--kubeconfig|--namespace|--output-file|--timeout|--include-namespaces|--exclude-namespaces|--probe-metrics|--detection-catalog|--image|--image-pull-secret)
                if [ "$has_value" = false ]; then
                    [ "$#" -gt 0 ] || fail "$arg requires a value."
                    value="$1"
                    shift
                fi
                case "$arg" in
                    --context) context="$value" ;;
                    --kubeconfig) kubeconfig="$value" ;;
                    --namespace) namespace="$value" ;;
                    --output-file) output_file="$value" ;;
                    --timeout) timeout="$value" ;;
                    --include-namespaces) include="$value" ;;
                    --exclude-namespaces) exclude="$value" ;;
                    --probe-metrics) probe_metrics="$value" ;;
                    --detection-catalog) catalog="$value" ;;
                    --image) image="$value" ;;
                    --image-pull-secret) pull_secret="$value" ;;
                esac ;;
            *) fail "Unknown option: $arg (see --help)." ;;
        esac
    done
}

validate_args() {
    local label='^[a-z0-9]([-a-z0-9]*[a-z0-9])?$'
    local subdomain='^[a-z0-9]([-a-z0-9.]*[a-z0-9])?$'
    local namespace_list='^[a-z0-9*,-]*$'
    local duration='^[1-9][0-9]*[sm]$'
    local image_ref='^[A-Za-z0-9][A-Za-z0-9./:@_-]*$'
    if ! [[ "$namespace" =~ $label ]] || [ "${#namespace}" -gt 63 ]; then
        fail "Invalid --namespace: $namespace"
    fi
    [[ "$include" =~ $namespace_list ]] || fail "--include-namespaces must be comma-separated namespace names; '*' is the only wildcard."
    [[ "$exclude" =~ $namespace_list ]] || fail "--exclude-namespaces must be comma-separated namespace names; '*' is the only wildcard."
    [[ "$timeout" =~ $duration ]] || fail "--timeout must be seconds or minutes, e.g. 300s or 10m."
    case "$probe_metrics" in true|false) ;; *) fail "--probe-metrics must be true or false." ;; esac
    case "$image" in
        ""|__*__) fail "No scanner image is set (this copy of the script was not published by CI); pass --image." ;;
    esac
    [[ "$image" =~ $image_ref ]] || fail "Invalid --image: $image"
    if [ -n "$pull_secret" ] && { ! [[ "$pull_secret" =~ $subdomain ]] || [ "${#pull_secret}" -gt 253 ]; }; then
        fail "Invalid --image-pull-secret: $pull_secret"
    fi
    if [ -n "$catalog" ] && { [ ! -f "$catalog" ] || [ ! -r "$catalog" ]; }; then
        fail "Cannot read --detection-catalog file: $catalog"
    fi
}

timeout_seconds() {
    case "$timeout" in
        *m) printf '%s\n' $(( ${timeout%m} * 60 )) ;;
        *) printf '%s\n' "${timeout%s}" ;;
    esac
}

kube() { kubectl "${kube_args[@]}" "$@"; }

select_cluster() {
    command -v kubectl >/dev/null 2>&1 || fail "kubectl is required; configure access to the cluster first."
    if [ -z "$context" ]; then
        if [ -n "$kubeconfig" ]; then
            context="$(kubectl --kubeconfig "$kubeconfig" config current-context 2>/dev/null)" || true
        else
            context="$(kubectl config current-context 2>/dev/null)" || true
        fi
        [ -n "$context" ] || fail "No current kubeconfig context; pass --context."
    fi
    # Pin the context so a context switch elsewhere cannot redirect this run.
    kube_args=(--context "$context")
    if [ -n "$kubeconfig" ]; then
        kube_args+=(--kubeconfig "$kubeconfig")
    fi
    info "Cluster context: $context"
    kube get --raw /version --request-timeout=15s >/dev/null 2>&1 || fail "Cannot reach the cluster for context $context."
}

# Succeeds when the object exists. The arguments are passed to kubectl get.
exists() {
    local out
    out="$(kube get "$@" --ignore-not-found -o name 2>&1)" || fail "Cannot check for $*: $out"
    [ -n "$out" ]
}

# Finds the scan access left by an earlier run or created by a cluster admin.
find_existing_access() {
    if exists namespace "$namespace"; then
        has_namespace=true
        if exists serviceaccount "$ACCESS_NAME" -n "$namespace"; then has_account=true; fi
    fi
    if exists clusterrole "$ACCESS_NAME"; then has_role=true; fi
    if exists clusterrolebinding "$ACCESS_NAME"; then
        has_binding=true
        check_binding
    fi
}

# A reused binding must give the scan ClusterRole to this namespace's
# ServiceAccount; the script never changes an existing object.
check_binding() {
    local out
    out="$(kube get clusterrolebinding "$ACCESS_NAME" \
        -o 'jsonpath={.roleRef.kind}/{.roleRef.name}{range .subjects[*]}{" "}{.kind}/{.namespace}/{.name}{end}' 2>&1)" ||
        fail "Cannot read ClusterRoleBinding $ACCESS_NAME: $out"
    if [[ "$out " != "ClusterRole/$ACCESS_NAME "* ]] || [[ "$out " != *" ServiceAccount/$namespace/$ACCESS_NAME "* ]]; then
        fail "ClusterRoleBinding $ACCESS_NAME does not give ClusterRole $ACCESS_NAME to ServiceAccount $namespace/$ACCESS_NAME. Run with the --namespace it names, or fix the binding."
    fi
}

# Adds "$1" to missing_permissions unless kubectl auth can-i allows the rest.
require() {
    local what="$1"
    shift
    kube auth can-i "$@" >/dev/null 2>&1 || missing_permissions="$missing_permissions $what;"
}

# Fail before creating anything when the run could not finish or report.
# Objects that already exist need no permission to create.
check_permissions() {
    [ "$has_namespace" = true ] || require "create namespaces" create namespaces
    [ "$has_account" = true ] || require "create serviceaccounts in $namespace" create serviceaccounts -n "$namespace"
    [ "$has_role" = true ] || require "create clusterroles" create clusterroles.rbac.authorization.k8s.io
    [ "$has_binding" = true ] || require "create clusterrolebindings" create clusterrolebindings.rbac.authorization.k8s.io
    if [ -n "$catalog" ]; then
        require "create configmaps in $namespace" create configmaps -n "$namespace"
        require "update configmaps in $namespace" patch configmaps -n "$namespace"
    fi
    require "create jobs in $namespace" create jobs.batch -n "$namespace"
    require "read pod logs in $namespace" get pods --subresource=log -n "$namespace"
    [ -z "$missing_permissions" ] || fail "Missing Kubernetes permissions:$missing_permissions ask a cluster admin to run this script."
}

labels() {
    local indent="$1"
    printf '%sapp.kubernetes.io/name: rt-stack-detector\n' "$indent"
    printf '%sapp.kubernetes.io/component: scan\n' "$indent"
    printf '%sapp.kubernetes.io/managed-by: rt-stack-detector-script\n' "$indent"
}

# Labels for the objects that belong to this run only.
run_labels() {
    labels "$1"
    printf '%srtifact.io/scan-run: "%s"\n' "$1" "$run_id"
}

namespace_manifest() {
    printf 'apiVersion: v1\nkind: Namespace\nmetadata:\n  name: %s\n  labels:\n' "$namespace"
    labels "    "
}

account_manifest() {
    cat <<EOF
apiVersion: v1
kind: ServiceAccount
metadata:
  name: $ACCESS_NAME
  namespace: $namespace
  labels:
$(labels "    ")
EOF
}

# Read-only access to the six lists the scanner uses; nothing else.
role_manifest() {
    cat <<EOF
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: $ACCESS_NAME
  labels:
$(labels "    ")
rules:
  - apiGroups: [""]
    resources: ["pods", "services"]
    verbs: ["list"]
  - apiGroups: ["apps"]
    resources: ["deployments", "daemonsets", "statefulsets", "replicasets"]
    verbs: ["list"]
EOF
}

binding_manifest() {
    cat <<EOF
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRoleBinding
metadata:
  name: $ACCESS_NAME
  labels:
$(labels "    ")
roleRef:
  apiGroup: rbac.authorization.k8s.io
  kind: ClusterRole
  name: $ACCESS_NAME
subjects:
  - kind: ServiceAccount
    name: $ACCESS_NAME
    namespace: $namespace
EOF
}

job_manifest() {
    local deadline="$1"
    cat <<EOF
apiVersion: batch/v1
kind: Job
metadata:
  name: $name
  namespace: $namespace
  labels:
$(run_labels "    ")
spec:
  backoffLimit: 0
  activeDeadlineSeconds: $deadline
  # The script deletes nothing; Kubernetes removes the finished Job and its pod.
  ttlSecondsAfterFinished: $JOB_TTL_SECONDS
  template:
    metadata:
      labels:
$(run_labels "        ")
        # A service-mesh sidecar would keep the pod running after the scan.
        sidecar.istio.io/inject: "false"
      annotations:
        sidecar.istio.io/inject: "false"
        linkerd.io/inject: disabled
    spec:
      serviceAccountName: $ACCESS_NAME
      restartPolicy: Never
      nodeSelector:
        kubernetes.io/os: linux
      securityContext:
        runAsNonRoot: true
        seccompProfile:
          type: RuntimeDefault
EOF
    if [ -n "$pull_secret" ]; then
        printf '      imagePullSecrets:\n        - name: %s\n' "$pull_secret"
    fi
    cat <<EOF
      containers:
        - name: scan
          image: "$image"
          imagePullPolicy: IfNotPresent
          args:
            - scan
            - --in-cluster
            - --timeout=$timeout
            - --probe-metrics=$probe_metrics
            - --include-namespaces=$include
            - --exclude-namespaces=$exclude
EOF
    if [ -n "$catalog" ]; then
        printf '            - --detection-catalog=/etc/rt-stack-detector/catalog.yaml\n'
    fi
    cat <<EOF
          env:
            # The scanner leaves its own namespace out of the report.
            - name: NAMESPACE
              valueFrom:
                fieldRef:
                  fieldPath: metadata.namespace
          resources:
            requests:
              cpu: 100m
              memory: 128Mi
            limits:
              cpu: "1"
              memory: 1Gi
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities:
              drop: ["ALL"]
EOF
    if [ -n "$catalog" ]; then
        cat <<EOF
          volumeMounts:
            - name: detection-catalog
              mountPath: /etc/rt-stack-detector
              readOnly: true
      volumes:
        - name: detection-catalog
          configMap:
            name: $CATALOG_NAME
EOF
    fi
}

show_pod_details() {
    info "Scan pod details:"
    { kube -n "$namespace" describe pods -l "rtifact.io/scan-run=$run_id" 2>&1 | tail -n 25 >&2; } || true
}

# Returns 0 when the Job succeeded and 1 when it failed; exits on start errors.
wait_for_job() {
    local deadline state succeeded failed failed_condition pod_state phase last_phase=""
    deadline=$(( $(date +%s) + $1 + 30 ))
    while :; do
        state="$(kube -n "$namespace" get job "$name" \
            -o 'jsonpath={.status.succeeded}/{.status.failed}/{.status.conditions[?(@.type=="Failed")].status}' 2>/dev/null)" || state=""
        IFS=/ read -r succeeded failed failed_condition <<EOF
$state
EOF
        if [ "${succeeded:-0}" -gt 0 ] 2>/dev/null; then return 0; fi
        if [ "${failed:-0}" -gt 0 ] 2>/dev/null || [ "$failed_condition" = True ]; then return 1; fi
        pod_state="$(kube -n "$namespace" get pods -l "rtifact.io/scan-run=$run_id" \
            -o 'jsonpath={range .items[*]}{.status.phase}{" "}{range .status.containerStatuses[*]}{.state.waiting.reason}{end}{"\n"}{end}' 2>/dev/null)" || pod_state=""
        phase="${pod_state%% *}"
        if [ -n "$phase" ] && [ "$phase" != "$last_phase" ]; then
            info "Scan pod: $phase"
            last_phase="$phase"
        fi
        case "$pod_state" in
            *ErrImagePull*|*ImagePullBackOff*|*InvalidImageName*|*CreateContainerConfigError*|*CreateContainerError*)
                show_pod_details
                fail "The scan pod could not start (${pod_state#* }). Check that the cluster can pull $image; use --image and --image-pull-secret for a private mirror." ;;
        esac
        if [ "$(date +%s)" -ge "$deadline" ]; then
            show_pod_details
            fail "Timed out waiting for the scan Job."
        fi
        sleep 2
    done
}

# Creates the object read from stdin unless it already exists. Another run
# creating it at the same moment is fine.
ensure() {
    local exists="$1" what="$2" out
    if [ "$exists" = true ]; then
        info "Using existing $what."
    elif out="$(kube create -f - 2>&1)"; then
        info "Created $what."
    elif ! printf '%s' "$out" | grep -q AlreadyExists; then
        fail "Cannot create $what: $out"
    fi
}

# One ConfigMap holds the catalog for every run; this run's file replaces it.
save_catalog() {
    kube -n "$namespace" create configmap "$CATALOG_NAME" --from-file=catalog.yaml="$catalog" --dry-run=client -o yaml |
        kube -n "$namespace" apply --server-side --force-conflicts --field-manager=rt-stack-detector-script -f - >/dev/null ||
        fail "Cannot save the detection catalog in ConfigMap $namespace/$CATALOG_NAME."
    kube -n "$namespace" label configmap "$CATALOG_NAME" --overwrite app.kubernetes.io/name=rt-stack-detector \
        app.kubernetes.io/component=scan app.kubernetes.io/managed-by=rt-stack-detector-script >/dev/null || true
    info "Saved the detection catalog in ConfigMap $namespace/$CATALOG_NAME."
}

# Removes only this run's local files; nothing in the cluster is deleted.
on_exit() {
    local status=$?
    trap - EXIT INT TERM
    if [ -n "$tmp" ]; then rm -rf -- "$tmp"; fi
    exit "$status"
}

main() {
    parse_args "$@"
    validate_args
    select_cluster
    find_existing_access
    check_permissions

    local seconds deadline job_succeeded=true
    seconds="$(timeout_seconds)"
    deadline=$(( seconds + START_ALLOWANCE_SECONDS ))
    run_id="$(od -An -N4 -tx1 /dev/urandom | tr -d ' \n')"
    name="$ACCESS_NAME-$run_id"
    tmp="$(mktemp -d "${TMPDIR:-/tmp}/stack-detector.XXXXXX")"
    trap on_exit EXIT
    trap 'exit 130' INT
    trap 'exit 143' TERM
    info "Image: $image"

    ensure "$has_namespace" "namespace $namespace" <<<"$(namespace_manifest)"
    ensure "$has_account" "ServiceAccount $namespace/$ACCESS_NAME" <<<"$(account_manifest)"
    ensure "$has_role" "ClusterRole $ACCESS_NAME" <<<"$(role_manifest)"
    ensure "$has_binding" "ClusterRoleBinding $ACCESS_NAME" <<<"$(binding_manifest)"
    if [ -n "$catalog" ]; then save_catalog; fi
    job_manifest "$deadline" | kube create -f - >/dev/null || fail "Cannot create the scan Job (see the error above)."
    info "Started Job $namespace/$name; waiting up to $(( deadline / 60 )) minutes..."

    wait_for_job "$deadline" || job_succeeded=false
    kube -n "$namespace" logs "job/$name" > "$tmp/pod.log" 2>/dev/null || true
    awk -v begin="$REPORT_BEGIN" -v end="$REPORT_END" \
        '$0 == begin { inside = 1; next } $0 == end { inside = 0; next } !inside { print "[pod] " $0 }' "$tmp/pod.log" >&2
    awk -v begin="$REPORT_BEGIN" -v end="$REPORT_END" \
        '$0 == end { inside = 0 } inside { print } $0 == begin { inside = 1 }' "$tmp/pod.log" > "$tmp/report.json"
    if [ ! -s "$tmp/report.json" ]; then
        show_pod_details
        fail "The scan pod did not produce a report."
    fi
    if [ -n "$output_file" ]; then
        cat "$tmp/report.json" > "$output_file" || fail "Cannot write $output_file."
        info "Report saved to $output_file."
    fi
    cat "$tmp/report.json"
    [ "$job_succeeded" = true ] || fail "The scan finished with an error; the report's \"error\" field has details."
    info "Scan completed."
}

main "$@"
